-- Tani Phase 8 — Scale: city gating, delivery abstraction, ranked search, recommendations, analytics and reliability.
create table if not exists public.market_cities(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,state_name text,is_active boolean not null default false,sort_order integer not null default 0,launch_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());insert into public.market_cities(code,name,state_name,is_active,sort_order) values('kosti','كوستي','النيل الأبيض',true,0) on conflict(code) do update set name=excluded.name,state_name=excluded.state_name;alter table public.market_cities enable row level security;drop policy if exists tani_market_cities_public_read on public.market_cities;create policy tani_market_cities_public_read on public.market_cities for select to anon,authenticated using(is_active or public.current_user_role()='admin');drop policy if exists tani_market_cities_admin_all on public.market_cities;create policy tani_market_cities_admin_all on public.market_cities for all to authenticated using(public.current_user_role()='admin') with check(public.current_user_role()='admin');

create table if not exists public.delivery_providers(code text primary key,display_name text not null,provider_type text not null check(provider_type in ('merchant','partner','platform')),is_active boolean not null default false,supported_cities text[] not null default '{}'::text[],public_config jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());insert into public.delivery_providers(code,display_name,provider_type,is_active,supported_cities) values('merchant_delivery','توصيل المتجر','merchant',true,array['kosti']) on conflict(code) do update set display_name=excluded.display_name,is_active=true;alter table public.delivery_providers enable row level security;drop policy if exists tani_delivery_providers_public_read on public.delivery_providers;create policy tani_delivery_providers_public_read on public.delivery_providers for select to anon,authenticated using(is_active);drop policy if exists tani_delivery_providers_admin_all on public.delivery_providers;create policy tani_delivery_providers_admin_all on public.delivery_providers for all to authenticated using(public.current_user_role()='admin') with check(public.current_user_role()='admin');

create table if not exists public.delivery_provider_assignments(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.sellers(id) on delete cascade,provider_code text not null references public.delivery_providers(code) on delete restrict,is_active boolean not null default true,merchant_config jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(seller_id,provider_code));alter table public.delivery_provider_assignments enable row level security;drop policy if exists tani_delivery_assignments_owner_read on public.delivery_provider_assignments;create policy tani_delivery_assignments_owner_read on public.delivery_provider_assignments for select to authenticated using(exists(select 1 from public.sellers s where s.id=delivery_provider_assignments.seller_id and s.user_id=(select auth.uid())) or public.current_user_role()=any(array['admin','support']));drop policy if exists tani_delivery_assignments_owner_write on public.delivery_provider_assignments;create policy tani_delivery_assignments_owner_write on public.delivery_provider_assignments for all to authenticated using(exists(select 1 from public.sellers s where s.id=delivery_provider_assignments.seller_id and s.user_id=(select auth.uid()) and s.verification_status='approved') or public.current_user_role()='admin') with check(exists(select 1 from public.sellers s where s.id=delivery_provider_assignments.seller_id and s.user_id=(select auth.uid()) and s.verification_status='approved') or public.current_user_role()='admin');

create or replace function public.delivery_quote(p_seller_id uuid,p_city text default null,p_area text default null) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select coalesce((select jsonb_build_object('seller_id',d.seller_id,'provider','merchant_delivery','fee',d.base_fee,'estimated_minutes',d.estimated_minutes,'delivery_area',d.delivery_area,'city',s.city,'area',p_area,'available',d.is_active and s.is_active and s.is_open) from public.delivery_settings d join public.sellers seller on seller.id=d.seller_id and seller.verification_status='approved' left join public.stores s on s.seller_id=d.seller_id and s.is_active where d.seller_id=p_seller_id and(p_city is null or lower(coalesce(s.city,''))=lower(p_city)) limit 1),jsonb_build_object('seller_id',p_seller_id,'available',false))$$;grant execute on function public.delivery_quote(uuid,text,text) to anon,authenticated;

create or replace function public.search_marketplace_ranked(p_query text,p_category_id uuid default null,p_city text default null,p_limit integer default 30,p_offset integer default 0) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from(select m.*,(case when lower(m.name)=lower(trim(coalesce(p_query,''))) then 100 else 0 end+case when lower(m.name) like lower(trim(coalesce(p_query,'')))||'%' then 40 else 0 end+case when lower(m.name) like '%'||lower(trim(coalesce(p_query,'')))||'%' then 20 else 0 end+case when lower(coalesce(m.description,'')) like '%'||lower(trim(coalesce(p_query,'')))||'%' then 8 else 0 end+coalesce(m.average_rating,0)*3+case when m.stock>0 then 5 else 0 end)rank_score from public.marketplace_product_cards m left join public.stores st on st.seller_id=m.seller_id and st.is_active where m.stock>0 and(p_category_id is null or m.category_id=p_category_id) and(p_city is null or lower(coalesce(st.city,''))=lower(p_city)) and(coalesce(trim(p_query),'')='' or lower(m.name) like '%'||lower(trim(p_query))||'%' or lower(coalesce(m.description,'')) like '%'||lower(trim(p_query))||'%' or lower(coalesce(m.store_name,'')) like '%'||lower(trim(p_query))||'%') order by rank_score desc,m.average_rating desc,m.created_at desc limit greatest(1,least(coalesce(p_limit,30),60)) offset greatest(coalesce(p_offset,0),0))x$$;grant execute on function public.search_marketplace_ranked(text,uuid,text,integer,integer) to anon,authenticated;

create or replace function public.recommended_products(p_limit integer default 12) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$with pref_categories as(select category_id,count(*)weight from(select p.category_id from public.favorites f join public.products p on p.id=f.product_id where f.user_id=(select auth.uid()) union all select p.category_id from public.orders o join public.order_items oi on oi.order_id=o.id join public.products p on p.id=oi.product_id where o.customer_id=(select auth.uid()) and o.status='delivered')q where category_id is not null group by category_id)select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from(select m.*,(coalesce(pc.weight,0)*20+coalesce(m.average_rating,0)*4+case when m.created_at>now()-interval '14 days' then 4 else 0 end)recommendation_score from public.marketplace_product_cards m left join pref_categories pc on pc.category_id=m.category_id where m.stock>0 order by recommendation_score desc,m.average_rating desc,m.created_at desc limit greatest(1,least(coalesce(p_limit,12),30)))x$$;revoke all on function public.recommended_products(integer) from public,anon;grant execute on function public.recommended_products(integer) to authenticated;

create or replace function public.merchant_inventory_health() returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare v_seller uuid;begin select id into v_seller from public.sellers where user_id=(select auth.uid()) and verification_status='approved' limit 1;if v_seller is null then raise exception 'approved merchant required';end if;return jsonb_build_object('seller_id',v_seller,'out_of_stock',(select count(*) from public.products where seller_id=v_seller and is_active and stock=0),'low_stock',(select count(*) from public.products where seller_id=v_seller and is_active and stock between 1 and 3),'inactive',(select count(*) from public.products where seller_id=v_seller and not is_active));end $$;revoke all on function public.merchant_inventory_health() from public,anon;grant execute on function public.merchant_inventory_health() to authenticated;

create or replace function public.weekly_marketplace_kpis(p_start timestamptz default null,p_end timestamptz default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare v_start timestamptz:=coalesce(p_start,now()-interval '7 days');v_end timestamptz:=coalesce(p_end,now());begin if public.current_user_role() not in('admin','support') then raise exception 'staff required';end if;return jsonb_build_object('start',v_start,'end',v_end,'orders',(select count(*) from public.orders where created_at>=v_start and created_at<v_end),'completed_orders',(select count(*) from public.orders where status='delivered' and created_at>=v_start and created_at<v_end),'cancelled_orders',(select count(*) from public.orders where status in('cancelled','rejected','failed') and created_at>=v_start and created_at<v_end),'gmv',(select coalesce(sum(total),0) from public.orders where status='delivered' and created_at>=v_start and created_at<v_end),'active_customers',(select count(distinct customer_id) from public.orders where created_at>=v_start and created_at<v_end),'active_merchants',(select count(distinct seller_id) from public.orders where created_at>=v_start and created_at<v_end),'repeat_customers',(select count(*) from(select customer_id from public.orders where status='delivered' and created_at<v_end group by customer_id having count(*)>1)q),'product_views',(select count(*) from public.app_events where event_name='product_view' and created_at>=v_start and created_at<v_end),'searches',(select count(*) from public.app_events where event_name in('search','search_submitted') and created_at>=v_start and created_at<v_end),'complaints',(select count(*) from public.complaints where created_at>=v_start and created_at<v_end),'app_errors',(select count(*) from public.app_errors where created_at>=v_start and created_at<v_end));end $$;revoke all on function public.weekly_marketplace_kpis(timestamptz,timestamptz) from public,anon;grant execute on function public.weekly_marketplace_kpis(timestamptz,timestamptz) to authenticated;

create table if not exists public.operational_alerts(id uuid primary key default gen_random_uuid(),type text not null,severity text not null default 'warning' check(severity in('info','warning','critical')),entity_type text,entity_id uuid,title text not null,details jsonb not null default '{}'::jsonb,status text not null default 'open' check(status in('open','acknowledged','resolved')),created_at timestamptz not null default now(),resolved_at timestamptz,resolved_by uuid references auth.users(id) on delete set null);alter table public.operational_alerts enable row level security;drop policy if exists tani_operational_alerts_staff_read on public.operational_alerts;create policy tani_operational_alerts_staff_read on public.operational_alerts for select to authenticated using(public.current_user_role()=any(array['admin','support']));drop policy if exists tani_operational_alerts_staff_update on public.operational_alerts;create policy tani_operational_alerts_staff_update on public.operational_alerts for update to authenticated using(public.current_user_role()=any(array['admin','support'])) with check(public.current_user_role()=any(array['admin','support']));

create index if not exists orders_created_status_idx on public.orders(created_at desc,status);create index if not exists orders_seller_created_idx on public.orders(seller_id,created_at desc);create index if not exists favorites_product_idx on public.favorites(product_id);create index if not exists app_events_name_created_idx on public.app_events(event_name,created_at desc);create index if not exists app_events_entity_idx on public.app_events(entity_type,entity_id,created_at desc);create index if not exists complaints_created_idx on public.complaints(created_at desc,status);

grant select on public.market_cities,public.delivery_providers to anon,authenticated;grant insert,update,delete on public.market_cities,public.delivery_providers to authenticated;grant select,insert,update,delete on public.delivery_provider_assignments to authenticated;grant select,update on public.operational_alerts to authenticated;
